import { expect, Page } from '@playwright/test';

/**
 * Page Object — Cart – Katalon Shop.
 * https://cms.demo.katalon.com/cart/
 *
 * Generated by the Zennx Playwright studio from a recorded session.
 * Locators live here and nowhere else, so a renamed button is one edit.
 */
export class CartPage {
    readonly page: Page;

    private readonly cartTotalsHeading = () => this.page.getByRole('heading', { name: 'Cart totals' });
    private readonly flyingNinjaQuantity = () => this.page.getByLabel('Flying Ninja quantity');
    private readonly updateCartButton = () => this.page.getByRole('button', { name: 'Update cart' });

    constructor(page: Page) {
        this.page = page;
    }

    async expectCartTotalsHeadingVisible(): Promise<void> {
        await expect(this.cartTotalsHeading()).toBeVisible();
    }

    async fillFlyingNinjaQuantity(value: string): Promise<void> {
        await this.flyingNinjaQuantity().fill(value);
    }

    async clickFlyingNinjaQuantity(): Promise<void> {
        await this.flyingNinjaQuantity().click();
    }

    async clickUpdateCartButton(): Promise<void> {
        await this.updateCartButton().click();
    }
}
